{
  "type": "request_information",
  "message": "I can help update the shipping address. First, I need to verify your account and locate the order.",
  "ask": {
    "email_or_name_zip": "Please provide the email on your account. If you don’t remember it, share your first and last name plus your ZIP code.",
    "order_id": "Please provide the order ID (starts with #, e.g., #W0000000).",
    "address_preference": "Do you want me to switch the order to the New York address already on your profile? If yes, I’ll confirm the full address before submitting. Otherwise, please provide the exact address (address1, address2, city, state, zip, country)."
  },
  "note": "Address changes are only possible if the order is still pending. I’ll list the change details and ask for your confirmation before proceeding."
}

{
  "type": "confirm_action",
  "message": "I found your account and located the recent pending order with two wristwatches (#W4219264). It’s currently set to ship to your Seattle address: 619 Broadway, Suite 484, Seattle, WA 98187, USA. I can switch it to the New York address you’ve used before: 144 Lakeview Drive, Suite 925, New York, NY 10228, USA.",
  "ask_for_confirmation": "Please confirm: Do you want me to update order #W4219264 to ship to the New York address above? Reply “Yes” to proceed or “No” to cancel. If the NY address should be different, please provide the correct full address."
}

{
  "type": "update_and_confirm",
  "message": "The shipping address for order #W4219264 has been updated to: 144 Lakeview Drive, Suite 925, New York, NY 10228, USA.",
  "proposed_item_modification": {
    "order_id": "#W4219264",
    "current_item": {
      "name": "Wristwatch",
      "item_id": "8886009523",
      "options": {
        "strap material": "silicone",
        "dial color": "blue"
      },
      "price": 1944.02
    },
    "new_item": {
      "name": "Wristwatch",
      "product_id": "6066914160",
      "item_id": "2407258246",
      "options": {
        "strap material": "metal",
        "dial color": "white"
      },
      "available": true,
      "price": 1822.82
    },
    "price_difference": {
      "type": "refund",
      "amount": 121.2
    }
  },
  "payment_method": {
    "default": "credit_card_1620755",
    "note": "We will use your saved credit card (credit_card_1620755) to process the $121.20 refund, unless you prefer an existing gift card."
  },
  "ask_for_confirmation": "Please confirm: Do you want me to modify the silicone-strap watch (item 8886009523) to the metal strap with white dial (item 2407258246) and process the $121.20 refund to credit_card_1620755? Reply “Yes” to proceed or “No” to cancel. Also, please confirm you have no other items to modify in this order, as item modifications can only be done once.",
  "reminder": "After we modify items on a pending order, we won’t be able to cancel or make further item changes to this order."
}

{
  "type": "action_result_and_next_steps",
  "message": "Done. Your order #W4219264 has been updated:\n- Shipping address: 144 Lakeview Drive, Suite 925, New York, NY 10228, USA\n- Item modification: Silicone-strap wristwatch (item 8886009523) changed to metal strap with white dial (item 2407258246)\n- Refund: $121.20 has been initiated to your saved credit card (credit_card_1620755).\n\nAbout the exchange: I see your delivered order #W3445693 includes Sneakers and an Air Purifier. I’ll look for an available Air Purifier variant with room size Large, HEPA filter, and Night Mode, then provide the exact item and any price difference for your confirmation.",
  "ask": {
    "payment_method_for_exchange": "If there’s a price difference for the purifier exchange, would you like me to use your saved credit card (credit_card_1620755) to pay/refund the difference?",
    "scope_confirmation": "Please confirm this exchange is only for the Air Purifier in order #W3445693. Note: exchanges for a delivered order can only be done once, so I’ll include all details before proceeding."
  }
}

{
  "type": "confirm_action",
  "message": "I found an available Air Purifier variant that matches your request for order #W3445693: Large room size, HEPA filter, and Night Mode.",
  "exchange_details": {
    "order_id": "#W3445693",
    "current_item": {
      "name": "Air Purifier",
      "item_id": "6341716129",
      "options": {
        "room size": "large",
        "filter type": "HEPA",
        "features": "smart sensors"
      },
      "price": 523.31
    },
    "new_item": {
      "name": "Air Purifier",
      "product_id": "3821016478",
      "item_id": "8302289002",
      "options": {
        "room size": "large",
        "filter type": "HEPA",
        "features": "night mode"
      },
      "available": true,
      "price": 547.55
    },
    "price_difference": {
      "type": "charge",
      "amount": 24.24,
      "payment_method_id": "credit_card_1620755"
    }
  },
  "reminders": [
    "Exchanges on a delivered order can only be done once.",
    "After confirming, the order status will change to 'exchange requested' and you’ll receive an email with return instructions. No need to place a new order."
  ],
  "ask_for_confirmation": "Please confirm: Do you want me to exchange the Air Purifier (item 6341716129) for the Large, HEPA, Night Mode variant (item 8302289002) and charge the $24.24 difference to your saved credit card ending in 1065? Reply “Yes” to proceed or “No” to cancel."
}
